    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05915.btn_rsn_del_onclick" });
    }
};

/**
 * @method
 * @name btn_rsn_uly_add_onclick
 * @description 「사유추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_rsn_uly_add_onclick = async function() {
    try {
        if (scwin.gubun === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-0012", ""));
            return;
        }
        scwin.getPar = scwin.getParRsnCd;
        scwin.setPar = scwin.setParRsnUlyCd;
        $c.lc.fn_PopFindLstRsnCd(RSNCD_SUSP);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05915.btn_rsn_uly_add_onclick" });
    }
};

/**
