    url += "&SCREN_ID=" + "ULDSTF05915.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=TRD_SUSP_INOUT";
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /* useupdate를 false로 지정함. */
    const sbmOptions2 = {
        id : "sbm_dts_Rsn",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Rsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_Rsn_Uly",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Rsn_Uly=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /* useupdate를 false로 지정함. */
    const sbmOptions4 = {
        id : "sbm_dts_Isu",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveTrs
 * @description 매매거래정지 사유는 매번 업무처리 번호를 세팅함
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    // 매매거래정지 사유는 매번 업무처리 번호를 세팅함
    // 사유별 추가,삭제가 있을수 있기때문
    dts_Rsn.setBroadcast(false);
    for (let i = 1; i <= dts_Rsn.getRowCount(); i++) {
        dts_Rsn.setCellData(i, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        dts_Rsn.setCellData(i, "ULY_HALT_YN", "N");
    }
    dts_Rsn.setBroadcast(true, true);
    dts_Rsn_Uly.setBroadcast(false);
    for (let i = 1; i <= dts_Rsn_Uly.getRowCount(); i++) {
        dts_Rsn_Uly.setCellData(i, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        dts_Rsn_Uly.setCellData(i, "ULY_HALT_YN", "Y");
    }
    dts_Rsn_Uly.setBroadcast(true, true);

    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }

    // ELW는 항상  종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    let vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx === TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx === TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "4",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_215 + ",DIV_IDX[0]=" + DIV_IDX_ASGN + ",DIV_IDX[1]=" + DIV_IDX_ISU_ELW + ",DIV_IDX[2]=" + DIV_IDX_RASN_ELW + ",DIV_IDX[3]=" + DIV_IDX_RASN_ULY
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/tradingSuspension.do",
        ref : "dts_Mst,dts_Isu,dts_Rsn,dts_Rsn_Uly",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

