 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParRsnCd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParRsnCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = "1";
    arrPar[1] = "06";
    return arrPar.length;
};

/**
 * @method
 * @name setParRsnCd
 * @description 선택된 사유코드 중복체크
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParRsnCd = function(arrPar) {
    // 선택된 사유코드 중복체크
    if (!$c.lc.fn_isNewValueForDataSet(dts_Rsn, "LD_HALT_RSN_CD", arrPar[0])) return;
    dts_Rsn.insertRow();
    dts_Rsn.setCellData(dts_Rsn.getRowPosition(), "LD_HALT_RSN_CD", arrPar[0]);
    dts_Rsn.setCellData(dts_Rsn.getRowPosition(), "HALT_RSN_NM", arrPar[1]);
    txb_TrdHaltGrndRegulNm.setValue(arrPar[2]);
};

/**
 * @method
 * @name setParRsnUlyCd
 * @description 선택된 사유코드 중복체크
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParRsnUlyCd = function(arrPar) {
    // 선택된 사유코드 중복체크
    if (!$c.lc.fn_isNewValueForDataSet(dts_Rsn_Uly, "LD_HALT_RSN_CD", arrPar[0])) return;
    dts_Rsn_Uly.insertRow();
    dts_Rsn_Uly.setCellData(dts_Rsn_Uly.getRowPosition(), "LD_HALT_RSN_CD", arrPar[0]);
    dts_Rsn_Uly.setCellData(dts_Rsn_Uly.getRowPosition(), "HALT_RSN_NM", arrPar[1]);
};

/**
 * @method
 * @name getParIsu
 * @description get Par Isu 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @param {*} param_dts param_dts
 * @returns {void}
 * @hidden N
 */
scwin.getParIsu = function(arrPar, param_dts) {
    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.gubun;
    $c.stf.copyDataSet(dts_Isu, param_dts);
};

/**
 * @method
 * @name setParIsu
 * @description set Par Isu 처리
 * @param {*} param_dts param_dts
 * @returns {void}
 * @hidden N
 */
scwin.setParIsu = function(param_dts) {
    // alert(dts_Isu.text);
    $c.stf.copyDataSet(param_dts, dts_Isu);
    // alert(dts_Isu.text);

};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (dts_Isu.getRowCount() === 0) {
        await $c.win.alert("[거래정지종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_TrdHaltStrtDd, "거래정지 지정", false)) return false;
    if (edt_TrdHaltEndDd.getValue() === "" && txb_TrdHaltEndDdDsc.getValue() === "") {
        await $c.win.alert("[거래정지해제일] 또는 [주석]을 입력하세요.");
        txb_TrdHaltEndDdDsc.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_TrdHaltEndDdDsc, 2000, "주석")) return false;
    if (edt_TrdHaltEndDd.getValue() !== "" && (edt_TrdHaltStrtDd.getValue() >= edt_TrdHaltEndDd.getValue())) {
        await $c.win.alert("[거래정지 해제일]은  [거래정지 지정일]이후로 입력하세요.");
        edt_TrdHaltEndDd.focus();
        return false;
    }
    if (dts_Rsn.getRowCount() === 0) {
        await $c.win.alert("[정지사유]를 선택하세요.");
        btn_rsn_add.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_TrdHaltGrndRegulNm, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_TrdHaltGrndRegulNm, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    if (scwin.gubun === '2' && dts_Rsn_Uly.getRowCount() === 0) {
        await $c.win.alert("[기초자산의 정지사유]를 선택하세요.");
        btn_rsn_uly_add.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "HALT_DESNRELS_TP_CD", scwin.haltTpCd);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
            await scwin.saveTrs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.saveTrs();
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        if (scwin.gubun === '1') {
            // 발행사 기준
            arr[0] = "68954E";
        } else if (scwin.gubun === '2') {
            // 기초자산 기준
            arr[0] = "68954F";
        }
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        // arr[4]; //ctnt
        arr[5] = $c.lc.fn_GetAddTitle(dts_Mst.getCellData(dts_Mst.getRowPosition(), "COM_NM")); // add  title

        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Mst, param_dts_mst);
        $c.stf.copyDataSet(dts_Rsn, param_dts2);
        $c.stf.copyDataSet(dts_Rsn_Uly, param_dts3);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "TGT_NM", scwin.Isur_nm);
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 740 + 5;
    const hgt = 790 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

